:root {
  color-scheme: only light;
  --bg: #eef4ff;
  --bg-deep: #dfe8f8;
  --panel: rgba(247, 250, 255, 0.95);
  --panel-solid: #f8fbff;
  --card: #ffffff;
  --border: #c9d7ef;
  --border-strong: rgba(24, 88, 184, 0.26);
  --border-glow: rgba(39, 144, 255, 0.16);
  --text: #14223c;
  --muted: #67758f;
  --accent: #2895ff;
  --accent-soft: #e7f2ff;
  --accent-strong: #163e8e;
  --accent-glow: rgba(40, 149, 255, 0.24);
  --warn: #b86b2f;
  --warn-soft: #f7e6d6;
  --danger: #b45050;
  --danger-soft: #f5dddd;
  --shadow: rgba(21, 42, 90, 0.14);
  --shadow-strong: rgba(8, 25, 62, 0.24);
  --ink-inverse: #f7fbff;
  --status-open: #446a91;
  --status-open-bg: #dde8f5;
  --status-wait: #9a6a28;
  --status-wait-bg: #f4e7d2;
  --status-progress: #8d3bdf;
  --status-progress-bg: #f0e6fd;
  --status-done: #6b6c76;
  --status-done-bg: #ebedf1;
  --status-invoice: #8e3b2e;
  --status-invoice-bg: #f5dfdb;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html,
body {
  margin: 0;
  min-height: 100%;
  color-scheme: only light;
}

body.is-auth-mode {
  height: 100vh;
  overflow: hidden;
}

body.is-signup-open {
  overflow: hidden;
}

body {
  font-family: "Trebuchet MS", "Segoe UI", sans-serif;
  color: var(--text);
  background:
    radial-gradient(circle at top left, rgba(255, 255, 255, 0.86), transparent 28%),
    radial-gradient(circle at right, rgba(41, 144, 255, 0.12), transparent 28%),
    radial-gradient(circle at 78% 14%, rgba(22, 62, 142, 0.14), transparent 24%),
    linear-gradient(180deg, var(--bg), var(--bg-deep));
}

button,
input,
select,
textarea {
  font: inherit;
}

button,
input,
select,
textarea,
fieldset {
  border-radius: 14px;
}

.app-shell {
  min-height: 100vh;
  padding: 12px;
}

.app-frame {
  width: 100%;
  min-height: calc(100vh - 24px);
  margin: 0;
  background: var(--panel);
  border: 1px solid rgba(219, 166, 209, 0.78);
  border-radius: 32px;
  box-shadow:
    0 28px 84px var(--shadow),
    inset 0 1px 0 rgba(255, 255, 255, 0.68),
    inset 0 0 0 1px rgba(240, 79, 151, 0.05);
  padding: 18px;
  backdrop-filter: blur(14px);
  display: grid;
  grid-template-columns: 68px minmax(220px, 280px) minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}

.app-frame.is-sidebar-collapsed {
  grid-template-columns: 68px 0 minmax(0, 1fr);
}

.app-frame.is-rail-hidden {
  grid-template-columns: 0 minmax(220px, 280px) minmax(0, 1fr);
}

.app-frame.is-rail-hidden.is-sidebar-collapsed {
  grid-template-columns: 0 0 minmax(0, 1fr);
}

.app-frame {
  position: relative;
}

.app-rail {
  position: sticky;
  top: 12px;
  z-index: 1700;
  min-height: calc(100vh - 60px);
  padding: 12px 9px;
  border-radius: 28px;
  border: 1px solid rgba(215, 146, 214, 0.82);
  background:
    radial-gradient(circle at 50% 0%, rgba(240, 79, 151, 0.22), transparent 30%),
    radial-gradient(circle at 72% 18%, rgba(123, 92, 255, 0.2), transparent 28%),
    linear-gradient(180deg, #efe6fb 0%, #e5daf7 52%, #dccff3 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.74),
    0 22px 40px rgba(92, 69, 140, 0.18);
  display: grid;
  grid-template-rows: auto auto 1fr;
  align-content: stretch;
  justify-items: center;
  justify-content: center;
  gap: 12px;
}

.app-frame.is-rail-hidden .app-rail {
  width: 0;
  min-width: 0;
  padding: 0;
  border: 0;
  opacity: 0;
  overflow: hidden;
  pointer-events: none;
}

.app-rail-logo {
  width: 42px;
  height: 42px;
  border-radius: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  background: linear-gradient(135deg, #f04f97, #7b5cff);
  color: #ffffff;
  font-size: 0.95rem;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 16px 28px rgba(145, 73, 192, 0.28);
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.app-rail-logo:hover {
  transform: translateY(-1px);
  box-shadow: 0 20px 32px rgba(145, 73, 192, 0.32);
}

.app-rail-nav {
  display: grid;
  gap: 8px;
  width: auto;
  justify-items: center;
  justify-self: center;
  align-content: start;
}

.app-rail-toolbar {
  width: auto;
  display: flex;
  justify-content: center;
  padding-top: 0;
  margin-top: -4px;
  opacity: 0.72;
  transition: opacity 180ms ease;
}

.app-rail-toolbar:hover {
  opacity: 1;
}

.app-rail-footer {
  display: none;
}

.app-sidebar {
  position: sticky;
  top: 12px;
  min-height: calc(100vh - 60px);
  display: grid;
  grid-template-rows: auto 1fr auto;
  align-content: stretch;
  gap: 12px;
  padding: 14px;
  border-radius: 26px;
  border: 1px solid rgba(223, 176, 225, 0.78);
  background:
    radial-gradient(circle at 18% 0%, rgba(240, 79, 151, 0.12), transparent 26%),
    radial-gradient(circle at 84% 8%, rgba(123, 92, 255, 0.1), transparent 24%),
    linear-gradient(180deg, rgba(247, 242, 253, 0.99), rgba(239, 232, 249, 0.99));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    0 18px 36px rgba(90, 76, 126, 0.1);
}

.app-frame.is-sidebar-collapsed .app-sidebar {
  padding: 0;
  border: 0;
  opacity: 0;
  pointer-events: none;
  overflow: hidden;
  min-height: 0;
}

.app-main {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 18px;
}

.sidebar-brand-pill {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 18px;
  width: 100%;
  border: 1px solid rgba(221, 203, 241, 0.58);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(249, 242, 255, 0.94));
  cursor: pointer;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.78);
  transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
}

.sidebar-brand-pill:hover {
  transform: translateY(-1px);
  border-color: rgba(219, 144, 197, 0.76);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    0 14px 26px rgba(126, 74, 140, 0.14);
}

.sidebar-header {
  display: flex;
  align-items: center;
  gap: 8px;
}

.sidebar-header .sidebar-brand-pill {
  flex: 1;
  min-width: 0;
}

.sidebar-footer {
  display: none;
}

.rail-toggle-button,
.rail-restore-button,
.sidebar-collapse-button {
  width: 32px;
  height: 32px;
  padding: 0;
  border-radius: 999px;
  border: 1px solid rgba(168, 177, 199, 0.58);
  background: rgba(255, 255, 255, 0.66);
  color: #47506b;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.9rem;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.8);
  transition: transform 180ms ease, background 180ms ease, border-color 180ms ease;
}

.rail-toggle-button:hover,
.rail-restore-button:hover,
.sidebar-collapse-button:hover {
  transform: translateX(-1px);
  background: rgba(255, 255, 255, 0.9);
  border-color: rgba(147, 157, 183, 0.76);
}

.rail-restore-button {
  position: absolute;
  left: 18px;
  top: 18px;
  z-index: 5;
}

.sidebar-brand-pill .auth-logo-mark {
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
}

.sidebar-brand-meta {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.sidebar-brand-meta strong {
  font-size: 0.95rem;
  font-weight: 700;
}

.sidebar-brand-meta span {
  color: var(--muted);
  font-size: 0.76rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar-section-label {
  margin: 8px 8px 2px;
  font-size: 0.73rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(96, 103, 128, 0.82);
}

.sidebar-groups {
  display: grid;
  gap: 8px;
  align-content: start;
  align-items: start;
}

.sidebar-group {
  display: grid;
  gap: 6px;
  align-self: start;
}

.sidebar-group-toggle {
  width: 100%;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 9px 12px;
  border-radius: 14px;
  border: 1px solid transparent;
  background: transparent;
  color: #485067;
}

.sidebar-group.is-open .sidebar-group-toggle {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(250, 246, 252, 0.88));
  border-color: rgba(220, 152, 211, 0.52);
}

.sidebar-group-icon {
  width: 29px;
  height: 29px;
  border-radius: 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(180deg, rgba(230, 234, 246, 0.96), rgba(223, 216, 245, 0.92));
  color: #5b507d;
  font-size: 0.84rem;
  font-weight: 600;
  letter-spacing: 0;
}

.icon-svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex: 0 0 auto;
}

.sidebar-group-label {
  min-width: 0;
  font-size: 0.9rem;
  font-weight: 700;
  text-align: left;
}

.sidebar-group-caret {
  color: #8a90a6;
  font-size: 0.8rem;
  transition: transform 160ms ease;
}

.sidebar-group.is-open .sidebar-group-caret {
  transform: rotate(0deg);
}

.sidebar-group:not(.is-open) .sidebar-group-caret {
  transform: rotate(-90deg);
}

.sidebar-group-items {
  display: grid;
  gap: 6px;
  padding-left: 8px;
}

.auth-screen {
  position: relative;
  isolation: isolate;
  min-height: 100vh;
  padding: clamp(18px, 3vw, 34px);
  overflow: hidden;
}

.auth-screen::before,
.auth-screen::after {
  content: "";
  position: absolute;
  inset: auto;
  border-radius: 999px;
  filter: blur(0);
  pointer-events: none;
  z-index: -2;
}

.auth-screen::before {
  width: min(42vw, 620px);
  height: min(42vw, 620px);
  top: -16%;
  right: -12%;
  background:
    radial-gradient(circle at 30% 30%, rgba(255, 248, 236, 0.92), rgba(255, 248, 236, 0) 34%),
    radial-gradient(circle, rgba(71, 163, 126, 0.18), rgba(71, 163, 126, 0) 72%);
  animation: auth-float 18s ease-in-out infinite alternate;
}

.auth-screen::after {
  width: min(36vw, 460px);
  height: min(36vw, 460px);
  bottom: -14%;
  left: -8%;
  background:
    radial-gradient(circle at 50% 50%, rgba(255, 246, 224, 0.82), rgba(255, 246, 224, 0) 40%),
    radial-gradient(circle, rgba(30, 106, 82, 0.1), rgba(30, 106, 82, 0) 74%);
  animation: auth-float 22s ease-in-out infinite alternate-reverse;
}

.auth-layout {
  width: min(1540px, 100%);
  min-height: calc(100vh - clamp(36px, 6vw, 68px));
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1.22fr) minmax(420px, 540px);
  gap: clamp(18px, 2vw, 24px);
}

.auth-showcase,
.auth-card {
  position: relative;
  overflow: hidden;
  border-radius: 34px;
  border: 1px solid rgba(213, 220, 207, 0.75);
  box-shadow: 0 26px 80px var(--shadow-strong);
  backdrop-filter: blur(18px);
}

.auth-showcase {
  background:
    linear-gradient(145deg, rgba(12, 20, 21, 0.98), rgba(17, 32, 31, 0.96) 40%, rgba(20, 61, 48, 0.9)),
    linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0));
  color: var(--ink-inverse);
}

.auth-showcase::before,
.auth-showcase::after,
.auth-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.auth-showcase::before {
  background:
    radial-gradient(circle at 18% 22%, rgba(126, 220, 186, 0.12), rgba(126, 220, 186, 0) 26%),
    radial-gradient(circle at 82% 18%, rgba(255, 246, 224, 0.2), rgba(255, 246, 224, 0) 24%),
    linear-gradient(120deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0));
}

.auth-showcase::after {
  inset: 22px;
  border-radius: 28px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.06) 1px, transparent 1px);
  background-size: 24px 24px;
  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.9), transparent 92%);
}

.auth-showcase-shell {
  position: relative;
  z-index: 1;
  min-height: 100%;
  display: grid;
  grid-template-rows: auto auto 1fr;
  gap: 30px;
  padding: clamp(28px, 4vw, 46px);
}

.auth-brand-row {
  display: inline-flex;
  align-items: center;
  gap: 14px;
}

.auth-brand-mark {
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(252, 245, 232, 0.22), rgba(252, 245, 232, 0.08)),
    rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: #fff6ea;
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.auth-brand-copy {
  display: grid;
  gap: 4px;
}

.auth-brand-copy strong {
  font-size: 1rem;
  letter-spacing: 0.04em;
}

.auth-brand-copy span {
  color: rgba(236, 246, 241, 0.68);
  font-size: 0.92rem;
}

.auth-copy {
  display: grid;
  gap: 18px;
  max-width: 72ch;
}

.auth-showcase .eyebrow {
  margin-bottom: 0;
  color: rgba(236, 246, 241, 0.74);
}

.auth-showcase h1 {
  margin: 0;
  font-size: clamp(3.2rem, 5.6vw, 6rem);
  line-height: 0.9;
  max-width: 11ch;
  letter-spacing: -0.04em;
}

.auth-intro {
  max-width: 58ch;
  color: rgba(236, 246, 241, 0.78);
  font-size: 1.02rem;
  line-height: 1.65;
}

.auth-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.auth-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 15px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(245, 252, 249, 0.06);
  color: rgba(245, 252, 249, 0.94);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.auth-chip::before {
  content: "";
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #f5dca7;
  box-shadow: 0 0 0 6px rgba(245, 220, 167, 0.12);
}

.auth-window,
.auth-trust-card {
  border-radius: 24px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.auth-visual-stack {
  display: grid;
  gap: 16px;
  align-self: end;
}

.auth-window {
  padding: 18px;
  background:
    linear-gradient(180deg, rgba(250, 247, 241, 0.09), rgba(250, 247, 241, 0.03)),
    rgba(255, 255, 255, 0.02);
}

.auth-window-header {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

.auth-window-header span {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.24);
}

.auth-window-header span:first-child {
  background: #ffb86c;
}

.auth-window-header span:nth-child(2) {
  background: #ffd86c;
}

.auth-window-header span:nth-child(3) {
  background: #8ad9b3;
}

.auth-window-body {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.auth-window-card {
  display: grid;
  gap: 10px;
  padding: 18px;
  border-radius: 22px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.05);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.auth-window-card span {
  display: inline-flex;
  align-items: center;
  color: rgba(245, 252, 249, 0.64);
  font-size: 0.78rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.auth-window-card strong {
  font-size: 1.05rem;
  line-height: 1.3;
}

.auth-window-card p {
  margin: 0;
  color: rgba(236, 246, 241, 0.76);
  line-height: 1.6;
}

.auth-window-card-primary {
  background:
    linear-gradient(180deg, rgba(250, 247, 241, 0.18), rgba(250, 247, 241, 0.08)),
    rgba(255, 255, 255, 0.06);
}

.auth-window-card-primary strong {
  font-size: 1.34rem;
  max-width: 12ch;
}

.auth-window-card-line {
  align-content: start;
}

.auth-window-line-track {
  height: 12px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.auth-window-line-fill {
  width: 76%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #f1dcae, #8ad9b3);
}

.auth-quote-card {
  padding: 20px 22px;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.auth-quote-card p {
  margin: 0 0 10px;
  font-size: 1.02rem;
  line-height: 1.65;
}

.auth-quote-card span {
  color: rgba(236, 246, 241, 0.7);
  font-size: 0.82rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.auth-panel {
  display: grid;
  align-items: center;
}

.auth-card {
  width: min(540px, 100%);
  margin-left: auto;
  background:
    linear-gradient(180deg, rgba(252, 249, 244, 0.94), rgba(250, 247, 241, 0.86)),
    linear-gradient(180deg, rgba(255, 255, 255, 0.58), rgba(255, 255, 255, 0.12));
  padding: clamp(26px, 4vw, 38px);
}

.auth-card::before {
  background:
    radial-gradient(circle at top right, rgba(126, 220, 186, 0.12), rgba(126, 220, 186, 0) 34%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.34), rgba(255, 255, 255, 0));
}

.auth-card-topline,
.auth-card-copy,
.auth-trust-row,
.auth-form,
.auth-card .form-error,
.auth-security-note {
  position: relative;
  z-index: 1;
}

.auth-card-topline {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 24px;
}

.auth-card-pill {
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 8px 12px;
  border-radius: 999px;
  background: rgba(20, 75, 59, 0.08);
  color: var(--accent-strong);
  border: 1px solid rgba(20, 75, 59, 0.08);
  font-size: 0.82rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.auth-card-pill-soft {
  background: rgba(255, 255, 255, 0.72);
}

.auth-card-copy .eyebrow {
  margin-bottom: 12px;
}

.auth-card h2 {
  margin: 0 0 12px;
  font-size: clamp(2.3rem, 3.4vw, 3.5rem);
  line-height: 0.96;
  letter-spacing: -0.04em;
}

.auth-card .intro {
  color: var(--muted);
  line-height: 1.65;
}

.auth-trust-row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin: 24px 0;
}

.auth-trust-card {
  display: grid;
  gap: 8px;
  padding: 16px;
  background: rgba(255, 255, 255, 0.54);
  border-color: rgba(213, 220, 207, 0.92);
}

.auth-trust-card strong {
  font-size: 0.96rem;
}

.auth-trust-card span {
  color: var(--muted);
  font-size: 0.9rem;
  line-height: 1.5;
}

.auth-form {
  display: grid;
  gap: 16px;
  margin-top: 0;
}

.auth-form .field {
  gap: 10px;
}

.auth-form .field > span {
  font-size: 0.83rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.auth-form input {
  border-radius: 18px;
  min-height: 58px;
  padding: 15px 16px;
  border-color: rgba(201, 211, 196, 0.98);
  background: rgba(255, 255, 255, 0.82);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.68);
}

.auth-form input::placeholder {
  color: rgba(104, 113, 100, 0.76);
}

.auth-form input:focus {
  background: rgba(255, 255, 255, 0.96);
  box-shadow:
    0 0 0 5px rgba(30, 106, 82, 0.09),
