.user-presence-option[data-presence="busy"] .user-presence-dot {
  background: #e06363;
  box-shadow: 0 0 0 4px rgba(224, 99, 99, 0.1);
}

.user-presence-option[data-presence="offline"] .user-presence-dot {
  background: #98a4b7;
}

.user-presence-option.is-active {
  color: var(--accent-strong);
  font-weight: 700;
  background: rgba(233, 239, 248, 0.92);
  border-radius: 10px;
}

.user-presence-option.is-active .user-presence-label {
  text-decoration: none;
}

.user-menu-metrics {
  display: grid;
  gap: 6px;
  margin-bottom: 12px;
}

.user-menu-metric {
  display: flex;
  align-items: baseline;
  justify-content: flex-start;
  gap: 10px;
  padding: 0;
  border: 0;
  background: transparent;
}

.user-menu-metric strong {
  font-size: 0.83rem;
  color: var(--text);
  line-height: 1.25;
  text-align: left;
}

.user-menu-actions {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  padding-top: 12px;
  border-top: 1px solid rgba(216, 223, 236, 0.88);
}

.user-menu-link-button {
  border: 0;
  background: transparent;
  padding: 0;
  color: var(--accent-strong);
  font-size: 0.86rem;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
}

.user-menu-link-danger {
  color: #a24f4f;
}

.user-menu-error {
  min-height: 0;
  font-size: 0.8rem;
  flex-basis: 100%;
  margin: 0;
}

body.is-profile-modal-open {
  overflow: hidden;
}

.profile-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 82;
  border: 0;
  padding: 0;
  background: rgba(16, 25, 52, 0.42);
  cursor: pointer;
}

.profile-modal {
  position: fixed;
  top: 24px;
  left: 50%;
  z-index: 83;
  width: min(920px, calc(100vw - 28px));
  max-height: calc(100dvh - 48px);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 0;
  padding: 0;
  overflow: hidden;
  transform: translateX(-50%);
  background:
    radial-gradient(circle at top right, rgba(45, 111, 219, 0.08), transparent 36%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(247, 250, 255, 0.96));
}

.profile-modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 22px 16px;
  border-bottom: 1px solid rgba(219, 226, 242, 0.88);
}

.profile-modal-head h3,
.profile-password-head h4 {
  margin: 0;
}

.profile-modal-body {
  min-height: 0;
  display: grid;
  gap: 16px;
  overflow: auto;
  padding: 18px 22px 22px;
}

.profile-form,
.profile-password-form {
  display: grid;
  gap: 16px;
}

.profile-password-form {
  padding-top: 16px;
  border-top: 1px solid rgba(219, 226, 242, 0.88);
}

.profile-avatar-row {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.profile-avatar-preview {
  width: 64px;
  min-width: 64px;
  height: 64px;
  border-radius: 18px;
  display: grid;
  place-items: center;
  overflow: hidden;
  color: #1e4f91;
  font-weight: 800;
  background: linear-gradient(135deg, rgba(239, 246, 255, 0.98), rgba(249, 250, 255, 0.94));
  border: 1px solid rgba(196, 210, 233, 0.9);
}

.profile-avatar-preview.has-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.profile-avatar-copy {
  min-width: 0;
  display: grid;
  gap: 8px;
  justify-items: start;
}

.profile-avatar-copy strong {
  color: #1f2940;
  font-size: 0.98rem;
}

.profile-form-grid,
.profile-password-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.profile-form-grid .field-span-full {
  grid-column: 1 / -1;
}

.profile-modal-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.profile-report-schedule {
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid rgba(191, 205, 230, 0.92);
  border-radius: 14px;
  background: rgba(248, 251, 255, 0.86);
}

.profile-report-sentence {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  color: #1f2940;
  font-weight: 700;
  line-height: 1.35;
}

.profile-report-sentence input[type="checkbox"] {
  width: 18px;
  height: 18px;
  margin: 0;
  accent-color: #1d74f5;
}

.profile-report-sentence input[type="time"] {
  width: 116px;
  min-height: 38px;
  padding: 8px 10px;
  border: 1px solid rgba(184, 202, 231, 0.95);
  border-radius: 10px;
  background: #ffffff;
  color: #15213a;
  font: inherit;
}

.profile-report-sentence input[type="time"]:disabled {
  color: #71819f;
  background: #eef3fb;
}

.profile-report-actions {
  align-items: stretch;
}

#profile-feedback,
#profile-password-feedback {
  min-height: 1.1rem;
  margin: 0;
}

@media (max-width: 720px) {
  .profile-modal {
    top: 8px;
    width: calc(100vw - 16px);
    max-height: calc(100dvh - 16px);
  }

  .profile-modal-head,
  .profile-modal-body {
    padding-left: 16px;
    padding-right: 16px;
  }

  .profile-form-grid,
  .profile-password-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}

.hero-copy {
  max-width: 60ch;
}

.eyebrow,
.section-kicker {
  margin: 0 0 10px;
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
}

.hero h1 {
  margin: 0 0 10px;
  font-size: clamp(2.2rem, 4vw, 4rem);
  line-height: 0.92;
}

.hero-copy-minimal {
  display: none;
}

.intro,
.helper-copy {
  margin: 0;
  color: var(--muted);
}

.connection-status {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin: 0;
  padding: 12px 14px;
  border-radius: 20px;
  border: 1px solid #e7ebf3;
  background: rgba(255, 255, 255, 0.86);
  box-shadow: 0 12px 32px rgba(43, 53, 84, 0.08);
  color: #263247;
  min-width: 220px;
}

.connection-status-copy {
  display: grid;
  gap: 2px;
}

.connection-status-label {
  color: #1f2940;
  font-size: 0.83rem;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: 0.01em;
}

.connection-status-meta {
  color: #7b8398;
  font-size: 0.74rem;
  line-height: 1.2;
}

.connection-status-indicator {
  width: 12px;
  height: 12px;
  border-radius: 999px;
  flex: 0 0 auto;
}

.connection-status.is-connecting .connection-status-indicator {
  width: 14px;
  height: 14px;
  border: 2px solid rgba(104, 117, 145, 0.22);
  border-top-color: #566683;
  background: transparent;
  animation: connection-spin 0.9s linear infinite;
}

.connection-status.is-live {
  border-color: #dfeee6;
  background: rgba(246, 252, 248, 0.92);
}

.connection-status.is-live .connection-status-indicator {
  background: #34b26e;
  box-shadow: 0 0 0 0 rgba(52, 178, 110, 0.35);
  animation: connection-pulse 1.8s ease-out infinite;
}

.connection-status.is-memory {
  border-color: #f0e0bf;
  background: rgba(255, 248, 233, 0.96);
}

.connection-status.is-memory .connection-status-indicator {
  background: #d5982c;
}

@keyframes connection-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes connection-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(52, 178, 110, 0.35);
  }

  70% {
    box-shadow: 0 0 0 8px rgba(52, 178, 110, 0);
  }

  100% {
    box-shadow: 0 0 0 0 rgba(52, 178, 110, 0);
  }
}

.summary-grid {
  width: min(760px, 100%);
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  margin-left: auto;
}

.summary-card,
.panel {
  background: var(--panel-solid);
  border: 1px solid var(--border);
  box-shadow:
    inset 0 0 0 1px rgba(240, 79, 151, 0.04),
    0 14px 30px rgba(108, 83, 153, 0.06);
}

.summary-card {
  border-radius: 16px;
  padding: 10px 12px;
  min-height: 88px;
  border-color: rgba(219, 166, 209, 0.58);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.84),
    inset 0 0 0 1px rgba(240, 79, 151, 0.04),
    0 10px 24px rgba(108, 83, 153, 0.06);
}

.summary-card span {
  display: block;
  margin-bottom: 6px;
  color: var(--muted);
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.summary-card strong {
  font-size: clamp(1.05rem, 1.8vw, 1.65rem);
  line-height: 1.05;
}

.tab-strip {
  display: grid;
  gap: 6px;
}

.tab-button {
  border: 1px solid transparent;
  background: transparent;
  color: var(--text);
  padding: 8px 11px;
  cursor: pointer;
  border-radius: 14px;
  text-align: left;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  column-gap: 10px;
  transition: background 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
}

.tab-button strong {
  font-size: 0.89rem;
  font-weight: 600;
}

.tab-button:hover {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.88), rgba(250, 241, 250, 0.8));
  border-color: rgba(219, 187, 230, 0.6);
}

.tab-button.is-active {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(251, 242, 255, 0.97));
  color: var(--text);
  border-color: rgba(220, 183, 232, 0.58);
  box-shadow: 0 10px 24px rgba(145, 92, 192, 0.12);
}

.tab-button-icon {
  width: 24px;
  height: 24px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(180deg, rgba(244, 233, 250, 0.96), rgba(235, 224, 249, 0.92));
  color: #6d5387;
  font-size: 0.76rem;
  font-weight: 600;
  letter-spacing: 0;
}

.tab-button.is-active .tab-button-icon {
  background: linear-gradient(135deg, rgba(240, 79, 151, 0.22), rgba(123, 92, 255, 0.24));
  color: #6a41b4;
}

.sidebar-link {
  padding: 8px 11px;
  border-radius: 12px;
  background: transparent;
  box-shadow: none;
}

.sidebar-link strong {
  font-size: 0.9rem;
  font-weight: 600;
}

.sidebar-link:hover {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.86), rgba(249, 241, 251, 0.76));
}

.sidebar-link.is-active {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(250, 242, 255, 0.97));
  border-color: rgba(220, 183, 232, 0.52);
  box-shadow: 0 8px 20px rgba(145, 92, 192, 0.12);
}

.rail-button {
  display: grid;
  align-items: center;
  justify-items: center;
  grid-template-columns: 1fr;
  grid-template-rows: auto;
  row-gap: 0;
  width: 48px;
  min-height: 48px;
  padding: 0;
  border-radius: 14px;
  border: 1px solid rgba(214, 166, 218, 0.9);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(244, 237, 252, 0.9));
  color: #584d70;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.82),
    0 6px 14px rgba(91, 103, 139, 0.08);
}

.rail-button:hover {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(249, 237, 248, 0.92));
  border-color: rgba(219, 166, 209, 0.88);
  color: #513962;
}

.rail-button.is-active {
  background: linear-gradient(180deg, #f05da9 0%, #d94aa8 45%, #8d3bdf 100%);
  border-color: rgba(172, 63, 194, 0.96);
  color: #ffffff;
  box-shadow:
    0 16px 30px rgba(173, 61, 191, 0.3),
    0 0 0 1px rgba(255, 255, 255, 0.14) inset;
}

.rail-icon {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  color: inherit;
  font-size: 1.02rem;
  font-weight: 700;
}

.rail-icon .icon-svg {
  width: 22px;
  height: 22px;
}

.sidebar-group-icon .icon-svg,
.tab-button-icon .icon-svg {
  width: 16px;
  height: 16px;
}

.rail-button.is-active .rail-icon {
  background: transparent;
}

.rail-label {
  display: none;
}

.sync-error {
  margin: 0 0 18px;
  padding: 12px 14px;
  border-radius: 16px;
  background: var(--danger-soft);
  border: 1px solid rgba(180, 80, 80, 0.24);
  color: var(--danger);
}

.workspace-view {
  display: grid;
  gap: 18px;
  min-width: 0;
}

.module-panel {
  min-height: 280px;
  display: grid;
  align-content: start;
  gap: 18px;
}

.module-copy {
  max-width: 68ch;
  margin: 0;
}

.module-chip-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.module-chip {
  display: inline-flex;
  align-items: center;
  padding: 10px 14px;
  border-radius: 999px;
  border: 1px solid rgba(173, 181, 210, 0.32);
  background: rgba(255, 255, 255, 0.86);
  color: #4a5168;
  font-size: 0.88rem;
  font-weight: 600;
}

.settings-module {
  display: grid;
  gap: 10px;
}

.settings-notifications-panel {
  display: grid;
  gap: 10px;
  padding: 14px 16px;
}

.settings-brand-panel {
  gap: 14px;
}

.settings-brand-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 12px 14px;
  border: 1px solid rgba(47, 104, 84, 0.14);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.78);
}

.settings-brand-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.settings-brand-copy strong {
  color: #172033;
  font-size: 0.94rem;
}

.settings-brand-copy span {
  color: #5c6a86;
  font-size: 0.78rem;
  line-height: 1.4;
}

.settings-brand-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.settings-brand-actions .ghost-button {
  min-height: 36px;
  white-space: nowrap;
}

.settings-stamp-layout {
  display: grid;
  grid-template-columns: 132px minmax(0, 1fr);
  gap: 14px;
  align-items: stretch;
  padding: 12px 14px;
  border: 1px solid rgba(79, 70, 229, 0.16);
  border-radius: 18px;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.88), rgba(248, 250, 252, 0.9));
}

.settings-stamp-preview {
  display: grid;
  place-items: center;
  min-height: 96px;
  padding: 10px;
  border: 1px dashed rgba(148, 163, 184, 0.85);
  border-radius: 14px;
  background:
    linear-gradient(45deg, rgba(226, 232, 240, 0.5) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(226, 232, 240, 0.5) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(226, 232, 240, 0.5) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(226, 232, 240, 0.5) 75%);
  background-color: #fff;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0;
  background-size: 16px 16px;
  color: #64748b;
  font-size: 0.75rem;
  font-weight: 700;
  text-align: center;
}

.settings-stamp-preview.has-stamp {
  border-style: solid;
}

.settings-stamp-preview img {
  max-width: 100%;
  max-height: 84px;
  object-fit: contain;
}

.settings-stamp-copy {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.settings-stamp-copy strong {
  color: #172033;
  font-size: 0.94rem;
}

.settings-stamp-copy > span {
  color: #5c6a86;
  font-size: 0.78rem;
  line-height: 1.4;
}

.settings-stamp-controls {
  display: grid;
  grid-template-columns: minmax(96px, auto) repeat(3, minmax(82px, 112px));
  gap: 8px;
  align-items: end;
}

.settings-stamp-controls > label:not(.field) {
  display: inline-flex;
  gap: 7px;
  align-items: center;
  min-height: 36px;
  color: #26324a;
  font-size: 0.8rem;
  font-weight: 700;
}

.settings-stamp-controls input[type="checkbox"] {
  width: 15px;
  height: 15px;
  accent-color: #4f46e5;
}

.settings-stamp-controls .field > span {
  font-size: 0.68rem;
}

.settings-stamp-controls .field > input {
  height: 36px;
}

.danger-ghost-button {
  border-color: rgba(185, 28, 28, 0.26);
  color: #a93131;
  background: rgba(254, 242, 242, 0.76);
}

.settings-notification-stack {
  display: grid;
  gap: 12px;
}

.settings-notification-group {
  display: grid;
  gap: 10px;
  padding: 12px 14px;
  border: 1px solid rgba(47, 104, 84, 0.14);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.78);
}

.settings-notification-group > strong {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(47, 104, 84, 0.76);
}

.settings-notification-inline {
  display: grid;
  grid-template-columns: minmax(160px, 210px) minmax(160px, 210px);
  gap: 10px;
  align-items: end;
}

.settings-notification-inline .field > span {
  font-size: 0.72rem;
}

.settings-notification-inline .field > input {
  height: 42px;
}

.settings-points-layout {
  display: grid;
  grid-template-columns: minmax(220px, 0.72fr) minmax(280px, 1fr);
  gap: 14px;
  align-items: stretch;
}

.settings-points-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.settings-points-preview {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.settings-points-preview > div {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid rgba(196, 208, 232, 0.88);
  border-radius: 16px;
  background:
    radial-gradient(circle at top right, rgba(124, 90, 255, 0.1), transparent 42%),
    #ffffff;
  box-shadow: 0 12px 26px rgba(40, 55, 95, 0.06);
}

.settings-points-preview span {
  color: #667085;
  font-size: 0.68rem;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.settings-points-preview strong {
  color: #111b36;
  font-size: 1.12rem;
  line-height: 1;
}

.settings-points-preview small {
  min-width: 0;
  overflow: hidden;
  color: #53627d;
  font-size: 0.74rem;
  font-weight: 760;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-service-factors {
  display: grid;
  gap: 10px;
  margin-top: 14px;
  padding: 12px;
  border: 1px solid rgba(196, 208, 232, 0.78);
  border-radius: 18px;
  background: linear-gradient(135deg, rgba(248, 250, 255, 0.96), rgba(255, 255, 255, 0.98));
}

.settings-service-factors-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.settings-service-factors-head h4 {
  margin: 0;
  color: #111b36;
  font-size: 0.98rem;
}

.settings-service-factors-head > span {
  flex: 0 0 auto;
  padding: 5px 9px;
  border-radius: 999px;
  background: rgba(91, 77, 255, 0.09);
  color: #4f37c7;
  font-size: 0.68rem;
  font-weight: 900;
}

.settings-service-factor-list {
  display: grid;
  gap: 7px;
  max-height: 300px;
  overflow: auto;
  padding-right: 2px;
}

.settings-service-factor-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 86px auto;
  gap: 10px;
  align-items: center;
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid rgba(217, 225, 238, 0.92);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.86);
}

.settings-service-factor-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.settings-service-factor-copy strong,
.settings-service-factor-copy small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-service-factor-copy strong {
  color: #13213f;
  font-size: 0.8rem;
}

.settings-service-factor-copy small,
.settings-service-factor-suffix {
  color: #667085;
  font-size: 0.68rem;
  font-weight: 780;
}

.settings-service-factor-row input {
  width: 86px;
  height: 34px;
  padding: 0 9px;
  border: 1px solid rgba(196, 208, 232, 0.95);
  border-radius: 10px;
