}

.settings-job-ai-card summary::-webkit-details-marker {
  display: none;
}

.settings-job-ai-card summary span {
  min-width: 0;
  overflow: hidden;
  color: #13213f;
  font-size: 0.82rem;
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-job-ai-card-body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 10px;
  padding: 0 12px 12px;
}

.settings-job-ai-card-body textarea {
  min-height: 86px;
  resize: vertical;
}

.settings-job-ai-card-body .field-span-full {
