.offer-summary-toggle.is-total::before {
  content: "T";
}

.offer-item-field.is-description {
  min-width: 0;
}

.offer-item-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}

.offer-item-optionals {
  display: grid;
  gap: 10px;
}

.offer-item-breakdowns {
  display: grid;
  gap: 10px;
  padding: 12px;
