.offer-item-breakdown-remove {
  min-width: 82px;
  min-height: 38px;
}

.offer-item-actions {
  display: flex;
  justify-content: flex-end;
}

.offer-item-total {
  display: grid;
  gap: 4px;
  align-content: center;
  justify-items: end;
  min-width: 88px;
}

.offer-item-total-label {
  color: var(--muted);
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.offer-item-total-value {
  font-weight: 700;
  color: var(--text);
  font-size: 0.9rem;
}

.offer-item-remove {
  min-width: 82px;
  min-height: 38px;
}

.offers-totals-card {
  display: grid;
