input,
select,
textarea {
  width: 100%;
  border: 1px solid rgba(220, 156, 212, 0.68);
  padding: 12px 14px;
  background: rgba(255, 255, 255, 0.96);
  color: var(--text);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.88),
