.status-storno-rn {
  color: #48515d;
  background: #d8dde4;
}

.priority-urgent {
  color: var(--status-invoice);
  background: var(--status-invoice-bg);
}

.priority-high {
  color: var(--status-open);
  background: var(--status-open-bg);
}

.priority-normal {
  color: var(--status-progress);
  background: var(--status-progress-bg);
}

.priority-niski-prioritet,
.priority-bez-prioriteta {
  color: var(--status-done);
  background: var(--status-done-bg);
}

.subsection-title {
  margin: 4px 0 0;
  font-size: 1.05rem;
  color: var(--text);
}

.contact-grid-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.contact-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
}

.contact-card {
  margin: 0;
  padding: 14px;
  border: 1px solid var(--border);
  background: #fff;
  border-radius: 18px;
}

.contact-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.contact-card-heading {
  display: grid;
  gap: 2px;
}

.contact-card-title {
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--text);
}

.contact-card-index {
  font-size: 0.8rem;
  color: var(--muted);
}

.contact-card-remove {
  border: 1px solid rgba(150, 160, 173, 0.32);
  background: #f7f8fb;
  color: var(--muted);
  border-radius: 999px;
  padding: 8px 12px;
  font-size: 0.82rem;
}

.contact-card-remove:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.contact-card .field + .field {
  margin-top: 10px;
}

.empty-inline {
  margin: 14px 0 0;
  color: var(--muted);
}

.locations-list-footer {
  display: flex;
  justify-content: center;
  padding-top: 14px;
}

.load-state {
  margin: 12px 0 0;
  color: var(--muted);
  font-size: 0.92rem;
}

.panel-work-orders {
  display: grid;
  gap: 16px;
  min-height: 0;
  background: linear-gradient(180deg, #fffaff, #faf6ff);
}

body.measurement-sheet-open {
  overflow: hidden;
}

body.is-dashboard-builder-open {
  overflow: hidden;
}

body.is-resizing-measurement-column {
  cursor: col-resize;
  user-select: none;
}

body.is-filling-measurement-cells {
  cursor: crosshair;
  user-select: none;
}

body.is-selecting-measurement-cells {
  cursor: cell;
  user-select: none;
}

body.is-selecting-measurement-cells .measurement-cell-input {
  pointer-events: none;
}

.measurement-sheet-modal {
  position: fixed;
  inset: 0;
  z-index: 240;
  display: grid;
  place-items: center;
  padding: 6px;
}

.measurement-sheet-backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  padding: 0;
  background: rgba(20, 24, 34, 0.28);
  backdrop-filter: blur(6px);
}

.measurement-sheet-panel {
  position: relative;
  z-index: 1;
  width: min(1920px, calc(100vw - 12px));
  height: calc(100dvh - 12px);
  max-height: calc(100dvh - 12px);
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr);
  align-items: start;
  gap: 10px;
  min-height: 0;
  padding: 12px 14px 14px;
  overflow: hidden;
  border-radius: 20px;
  border: 1px solid rgba(219, 206, 236, 0.92);
  background: linear-gradient(180deg, #fffaff, #f7f1fc);
  box-shadow: 0 28px 88px rgba(88, 67, 136, 0.24);
}

.measurement-sheet-panel > * {
  min-width: 0;
}

.work-order-editor-backdrop {
  position: fixed;
  inset: 0;
  z-index: 36;
  background: rgba(17, 21, 31, 0.32);
  backdrop-filter: blur(6px);
}

body.is-work-order-editor-open {
  overflow: hidden;
}

.work-order-editor-panel {
  padding: 0;
  overflow: hidden;
  background: linear-gradient(180deg, #fffaff, #f5effb);
}

.work-order-editor-panel.is-modal-open {
  position: fixed;
  top: 10px;
  left: 50%;
  z-index: 37;
  width: min(1840px, calc(100vw - 12px));
  height: calc(100vh - 20px);
  max-height: none;
  overflow: hidden;
  transform: translateX(-50%);
  border: 1px solid rgba(206, 212, 228, 0.94);
  box-shadow: 0 28px 88px rgba(43, 53, 84, 0.24);
  border-radius: 28px;
}

.work-order-editor-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(340px, 24vw, 420px);
  gap: 0;
  height: 100%;
  min-height: 0;
}

.work-order-editor-main {
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 0;
  background: linear-gradient(180deg, #fffaff, #f6f0fb);
  overflow: hidden;
}

.work-order-editor-main.is-document-panel-active {
  background:
    linear-gradient(180deg, rgba(250, 236, 245, 0.94), rgba(247, 241, 253, 0.98)),
    linear-gradient(180deg, #fffaff, #f6f0fb);
  box-shadow: inset 0 0 0 2px rgba(192, 108, 214, 0.24);
}

.work-order-editor-fixed-head {
  display: grid;
  gap: 0;
  padding: 18px 20px 0;
  background: linear-gradient(180deg, rgba(255, 251, 255, 0.99), rgba(247, 239, 252, 0.96));
  border-bottom: 1px solid rgba(232, 236, 245, 0.9);
}

.work-order-editor-body {
  min-width: 0;
  min-height: 0;
  overflow: auto;
  padding: 14px 20px 20px;
  display: grid;
  align-content: start;
  gap: 14px;
  scrollbar-gutter: stable;
  overflow-anchor: none;
}

.work-order-editor-body:focus {
  outline: none;
}

.work-order-editor-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: 0;
  padding: 0;
  background: transparent;
  border-bottom: 0;
  backdrop-filter: none;
}

.work-order-editor-breadcrumb {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: #667089;
  font-size: 0.84rem;
  font-weight: 600;
}

.work-order-editor-type-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 34px;
  height: 34px;
  padding: 0 10px;
  border-radius: 12px;
  background: linear-gradient(135deg, #f04f97, #7b5cff);
  color: #fff;
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.work-order-editor-hero {
  display: none;
  grid-template-columns: minmax(0, 0.82fr) minmax(0, 1.18fr);
  align-items: start;
  gap: 16px;
  padding: 14px 16px;
  border-radius: 24px;
  border: 1px solid #e3e8f3;
  background:
    radial-gradient(circle at top right, rgba(245, 231, 237, 0.78), transparent 34%),
    linear-gradient(180deg, #ffffff, #f8fafd);
  box-shadow: 0 14px 34px rgba(46, 55, 84, 0.07);
}

.work-order-editor-hero-copy {
  display: grid;
  align-content: start;
  gap: 6px;
}

.work-order-editor-hero-copy h2 {
  margin: 0;
  color: #1d2434;
  font-size: 1.18rem;
  line-height: 1.12;
}

.work-order-editor-company-summary {
  display: grid;
  gap: 3px;
}

.work-order-editor-company-primary {
  color: #223047;
  font-size: 0.92rem;
  font-weight: 800;
  line-height: 1.35;
}

.work-order-editor-company-line {
  color: #67738a;
  font-size: 0.78rem;
  line-height: 1.4;
}

.work-order-editor-company-line.is-placeholder {
  color: #8a93a7;
}

.work-order-editor-subtitle {
  margin: 0;
  color: #6d7589;
  font-size: 0.78rem;
  line-height: 1.4;
}

.work-order-editor-meta {
  display: grid;
  gap: 10px;
  align-content: start;
}

.work-order-editor-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
}

.work-order-editor-chip {
  min-height: 26px;
  padding: 0 11px;
  font-size: 0.7rem;
  font-weight: 800;
}

.work-order-editor-tag-chip {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 0 10px;
  border-radius: 999px;
  background: #f3f6fb;
  border: 1px solid #dce4f0;
  color: #596780;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.work-order-editor-tag-chip.is-neutral {
  background: #f3f6fb;
  border-color: #dce4f0;
  color: #53627c;
}

.work-order-editor-tag-chip.is-soft {
  background: #f7f0e3;
  border-color: #ebddc2;
  color: #7b6432;
}

.work-order-editor-tag-chip.is-accent {
  background: #f7d7db;
  border-color: #efc3c9;
  color: #7c4050;
}

.work-order-editor-facts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 10px;
}

.work-order-editor-meta-item {
  display: grid;
  grid-template-columns: 24px minmax(0, auto);
  gap: 8px;
  align-items: start;
  min-width: 0;
  min-height: 62px;
  padding: 10px 12px;
  border-radius: 16px;
  border: 1px solid #e2e8f3;
  background: rgba(248, 250, 253, 0.98);
}

.work-order-editor-meta-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 8px;
  background: #f3f6fd;
  color: #65749a;
}

.work-order-editor-meta-icon svg {
  width: 14px;
  height: 14px;
  display: block;
}

.work-order-editor-meta-body {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.work-order-editor-meta-label {
  color: #8a92a6;
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.work-order-editor-meta-value {
  color: #273042;
  font-size: 0.72rem;
  font-weight: 700;
  line-height: 1.3;
  word-break: break-word;
}

.work-order-editor-assignees {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.work-order-editor-assignees-empty {
  color: #8d95a9;
  font-size: 0.74rem;
  font-weight: 600;
}

.work-order-editor-meta-item.is-assignee-group {
  align-items: center;
}

.work-order-editor-form {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  gap: 14px;
}

.work-order-editor-section {
  display: grid;
  gap: 12px;
  padding: 14px;
  border-radius: 18px;
  border: 1px solid #dde4f0;
  background: rgba(255, 255, 255, 0.98);
}

.work-order-editor-section.is-overview,
.work-order-editor-section.is-client,
.work-order-editor-section.is-documents {
  grid-column: 1 / -1;
}

.work-order-editor-section.is-service,
.work-order-editor-section.is-notes {
  align-self: start;
}

.work-order-editor-section-head {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 12px;
}

.work-order-editor-section-head h3 {
  margin: 2px 0 0;
  color: #232b3d;
  font-size: 0.98rem;
}

.work-order-editor-section-kicker {
  margin: 0;
  color: #8b93a8;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.work-order-editor-subgrid {
  display: grid;
  gap: 10px;
}

.work-order-editor-subsection {
  display: grid;
  gap: 10px;
  padding: 12px;
  border-radius: 16px;
  border: 1px solid #e5ebf5;
  background: linear-gradient(180deg, #fafcff, #f5f8fd);
}

.work-order-editor-subsection-head {
  color: #5d6882;
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.form-grid-work-order-essentials {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px 28px;
}

.form-grid-client-identity {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.form-grid-client-location,
.form-grid-client-contact,
.form-grid-service-meta {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.form-grid-service-main {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.form-grid-service-training {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.form-grid-notes {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.form-grid-notes .field-span-full {
  grid-column: auto;
}

.work-order-executors-field {
  grid-column: span 2;
  min-width: 0;
}

.work-order-editor-form .field {
  padding: 10px;
  border-radius: 16px;
  border: 1px solid #e1e6f0;
  background: #ffffff;
  transition: border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease;
}

.work-order-editor-form .field:focus-within {
  border-color: #cfd6e8;
  box-shadow: 0 0 0 4px rgba(102, 118, 169, 0.08);
}

.work-order-editor-form .field.is-primary-field {
  border-color: #d8dfed;
  background: linear-gradient(180deg, #fdfefe, #f7f9fd);
}

.work-order-editor-form .field > span,
.work-order-field-heading {
  color: #8991a6;
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.work-order-field-heading {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.work-order-field-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 8px;
  border: 1px solid #dde4f0;
  background: #f6f8fc;
  color: #647695;
}

.work-order-field-icon svg {
  width: 13px;
  height: 13px;
  display: block;
}

.work-order-field-label {
  display: inline-flex;
  align-items: center;
}

.work-order-editor-form input,
.work-order-editor-form select,
.work-order-editor-form textarea {
  border-radius: 12px;
  border: 1px solid #dce3ef;
  background: #f5f8fc;
}

.work-order-editor-section.is-overview {
  gap: 14px;
  padding-bottom: 16px;
}

.work-order-editor-section.is-overview .work-order-editor-section-head {
  padding-bottom: 2px;
}

.work-order-editor-section.is-overview .field {
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  display: grid;
  grid-template-columns: 144px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
}

.work-order-editor-section.is-overview .field:focus-within {
  box-shadow: none;
  border-color: transparent;
}

.work-order-editor-section.is-overview .field > input,
.work-order-editor-section.is-overview .field > select {
  background: #ffffff;
}

.work-order-inline-executor-picker,
.work-order-editor-executor-picker {
  width: 100%;
  min-width: 0;
}

.work-order-editor-executor-trigger {
  width: 100%;
  min-height: 46px;
  align-items: flex-start;
  justify-content: flex-start;
  gap: 10px;
  padding: 6px 10px;
  border-radius: 14px;
  background: #f5f8fc;
  box-shadow: none;
}

.work-order-editor-executor-trigger-stack {
  flex-wrap: wrap;
  gap: 6px;
}

.work-order-editor-executor-trigger .work-order-mini-executor {
  width: 30px;
  height: 30px;
}

.work-order-editor-executor-trigger-label {
  min-width: 0;
  color: #31405f;
  font-size: 0.78rem;
  font-weight: 700;
  line-height: 1.3;
  text-align: left;
  white-space: normal;
  overflow-wrap: anywhere;
  flex: 1 1 auto;
  padding-top: 3px;
}

.work-order-editor-executor-trigger-label.is-placeholder {
  color: #7d879d;
}

.work-order-editor-executor-trigger > .executor-avatar-icon.is-placeholder {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 999px;
  background: #edf2fb;
  color: #6a7897;
  flex-shrink: 0;
}

.work-order-editor-executor-trigger > .executor-avatar-icon.is-placeholder svg {
  width: 16px;
  height: 16px;
  display: block;
}

.form-grid-work-order-essentials > #work-order-company-preview {
  grid-column: 1 / -1;
  display: none;
}

.work-order-inline-note {
  grid-column: 1 / -1;
  padding-top: 10px;
  border-top: 1px solid #edf1f7;
  grid-template-columns: 1fr;
  align-items: stretch;
  gap: 8px;
}

.work-order-inline-note textarea {
  min-height: 88px;
  background: #ffffff;
}

.form-grid-client-contact > .field:first-child {
  grid-column: span 2;
}

.form-grid-service-meta > .field:first-child,
.form-grid-service-meta > .field:nth-child(2) {
  grid-column: span 2;
}

.work-order-editor-form textarea {
  min-height: 164px;
}

.work-order-editor-panel.is-modal-open {
  top: 12px;
  width: min(1580px, calc(100vw - 20px));
  height: calc(100vh - 24px);
  border-radius: 24px;
}

.work-order-editor-shell {
  grid-template-columns: minmax(0, 1fr) 405px;
}

.work-order-editor-fixed-head {
  padding: 12px 16px 0;
}

.work-order-editor-body {
  padding: 10px 16px 16px;
  gap: 10px;
}

.work-order-editor-topbar {
  gap: 10px;
}

.work-order-editor-type-mark {
  min-width: 30px;
  height: 30px;
  border-radius: 10px;
}

.work-order-editor-form {
  gap: 10px;
}

.work-order-editor-section {
  gap: 9px;
  padding: 10px 12px;
  border-radius: 16px;
}

.work-order-editor-section-head h3 {
  font-size: 0.92rem;
}

.work-order-editor-section.is-overview {
  gap: 10px;
  padding-bottom: 12px;
}

.form-grid-work-order-essentials {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px 10px;
}

.work-order-editor-section.is-overview .field {
  grid-template-columns: minmax(104px, 0.34fr) minmax(0, 1fr);
  gap: 8px;
}

.work-order-editor-section.is-overview .field > input,
.work-order-editor-section.is-overview .field > select,
.work-order-editor-form input,
.work-order-editor-form select {
  min-height: 40px;
}

.work-order-field-icon {
  width: 20px;
  height: 20px;
  border-radius: 7px;
}

.work-order-field-icon svg {
  width: 12px;
  height: 12px;
}

.work-order-client-bundle {
  display: grid;
  gap: 8px;
  padding: 10px;
  border: 1px solid rgba(130, 153, 196, 0.32);
  border-radius: 16px;
  background:
    linear-gradient(90deg, rgba(230, 247, 239, 0.76), rgba(255, 255, 255, 0.94)),
    #ffffff;
  box-shadow: inset 4px 0 0 rgba(70, 164, 116, 0.42);
}

.work-order-client-bundle-head {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  color: #2f4f43;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.work-order-client-bundle-icon {
  display: inline-flex;
  width: 22px;
  height: 22px;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: #2f7a54;
  background: rgba(236, 249, 241, 0.98);
  border: 1px solid rgba(75, 153, 103, 0.22);
}

.work-order-client-bundle-icon svg {
  width: 14px;
  height: 14px;
}

.work-order-client-bundle-grid {
  display: grid;
  grid-template-columns: minmax(220px, 1.15fr) minmax(240px, 1.35fr) minmax(150px, 0.7fr);
  gap: 8px 10px;
}

.work-order-client-bundle-grid .field {
  grid-template-columns: 94px minmax(0, 1fr);
}

.work-order-executors-field {
  grid-column: span 3;
}

.work-order-editor-executor-trigger {
  min-height: 40px;
  padding: 5px 9px;
  align-items: center;
}

.work-order-editor-executor-trigger .work-order-mini-executor {
  width: 26px;
  height: 26px;
}

.work-order-inline-note {
  padding-top: 8px;
}

.work-order-inline-note textarea,
.work-order-editor-form textarea {
  min-height: 86px;
}

.work-order-editor-subsection {
  gap: 8px;
  padding: 10px;
  border-radius: 14px;
}

.work-order-document-dropzone {
  padding: 12px 14px;
  grid-template-columns: 36px minmax(0, 1fr);
}

.work-order-document-dropzone-mark {
  width: 36px;
  height: 36px;
  border-radius: 12px;
}

.work-order-document-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  min-height: 32px;
