  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 10px;
}

.measurement-toolbar-formula input {
  min-height: 44px;
  width: 100%;
  padding: 0 16px;
  border: 1px solid #d9deea;
  border-radius: 14px;
  background: #ffffff;
  color: #1f2433;
  box-shadow: none;
