  border-radius: 12px;
  background: linear-gradient(180deg, #ffffff, #eef5ff);
  color: #2452a7;
  box-shadow: 0 8px 18px rgba(43, 92, 181, 0.12);
  cursor: pointer;
  transition:
    transform 120ms ease,
    border-color 120ms ease,
    box-shadow 120ms ease,
    color 120ms ease,
    background 120ms ease;
}

.work-item-document-button {
  color: #385267;
