@keyframes auth-float {
  from {
    transform: translate3d(0, 0, 0) scale(1);
  }

  to {
    transform: translate3d(18px, 22px, 0) scale(1.08);
  }
}

.auth-screen {
  position: relative;
  min-height: 100vh;
  padding: 0;
  overflow: hidden;
  background:
    linear-gradient(135deg, #5fc8f7 0%, #76a8ff 34%, #9c63ff 68%, #ef45d7 100%);
}

.auth-screen::before,
.auth-screen::after {
  content: "";
  position: absolute;
  pointer-events: none;
  z-index: 0;
}

.auth-screen::before {
  top: -12%;
  left: -10%;
  width: min(42vw, 520px);
  height: min(58vw, 700px);
  transform: rotate(18deg);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.2), rgba(255, 255, 255, 0.05));
  border-radius: 38px;
  opacity: 0.5;
  filter: blur(2px);
}

.auth-screen::after {
  right: -10%;
  bottom: -8%;
  width: min(34vw, 380px);
  height: min(34vw, 380px);
  background:
    radial-gradient(circle at 50% 50%, rgba(255, 255, 255, 0.22), rgba(255, 255, 255, 0) 72%);
  filter: blur(10px);
}

.auth-shell {
  position: relative;
  z-index: 1;
  min-height: 100vh;
  display: grid;
  grid-template-rows: auto 1fr;
  padding: clamp(28px, 3vw, 40px);
}

.auth-topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
}

.auth-logo {
  display: inline-flex;
  align-items: center;
  gap: 16px;
}

.auth-logo-mark {
  position: relative;
  width: 48px;
  height: 48px;
}

.auth-logo-mark span {
  position: absolute;
  display: block;
  border-radius: 999px;
  background: linear-gradient(180deg, #86a2ff 0%, #6d65ff 48%, #6b3cff 100%);
  box-shadow: 0 10px 26px rgba(103, 77, 255, 0.28);
}

.auth-logo-mark span:first-child {
  inset: 2px 18px 18px 2px;
  transform: rotate(-28deg);
}

.auth-logo-mark span:last-child {
  inset: 18px 2px 2px 18px;
  transform: rotate(-28deg);
}

.auth-logo-word {
  color: #ffffff;
  font-size: clamp(2rem, 3vw, 2.6rem);
  font-weight: 700;
  letter-spacing: -0.04em;
}

.auth-nav {
  display: inline-flex;
  align-items: center;
  gap: 28px;
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.86rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.auth-center {
  display: grid;
  place-items: center;
  padding: clamp(32px, 9vh, 120px) 16px 140px;
}

.auth-form-shell {
  width: min(100%, 460px);
  display: grid;
  justify-items: stretch;
  gap: 18px;
  text-align: center;
}

.auth-kicker {
  margin: 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.82rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.auth-form-shell h1 {
  margin: 0;
  color: #ffffff;
  font-size: clamp(3.1rem, 5vw, 4.5rem);
  line-height: 0.94;
  letter-spacing: -0.05em;
}

.auth-subtitle {
  margin: -4px 0 12px;
  color: rgba(255, 255, 255, 0.72);
  font-size: 1.1rem;
}

.auth-form {
  display: grid;
  gap: 16px;
}

.auth-form .field {
  gap: 0;
}

.auth-form .field > span {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.auth-form input {
  min-height: 70px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(24, 24, 30, 0.92);
  color: #ffffff;
  padding: 18px 22px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    0 12px 32px rgba(0, 0, 0, 0.24);
}

.auth-form input::placeholder {
  color: rgba(255, 255, 255, 0.44);
}

.auth-form input:focus {
  outline: none;
  border-color: rgba(132, 93, 255, 0.72);
  background: rgba(28, 28, 36, 0.96);
  box-shadow:
    0 0 0 4px rgba(118, 78, 255, 0.14),
    0 18px 42px rgba(44, 20, 120, 0.22);
}

.auth-password-wrap {
  position: relative;
}

.auth-password-wrap input {
  padding-right: 98px;
}

.auth-inline-button {
  position: absolute;
  top: 9px;
  right: 9px;
  min-width: 78px;
  min-height: 52px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.82);
}

.auth-submit-button {
  min-height: 72px;
  border-radius: 18px;
  background: linear-gradient(90deg, #6d3cff 0%, #8a42ff 100%);
  color: #ffffff;
  font-size: 1rem;
  font-weight: 700;
  box-shadow: 0 22px 60px rgba(92, 51, 255, 0.32);
}

.auth-submit-button:disabled,
.auth-inline-button:disabled {
  opacity: 0.72;
  cursor: wait;
}

.auth-meta {
  margin: 4px 0 0;
  color: rgba(255, 255, 255, 0.66);
  font-size: 0.98rem;
}

.auth-screen .form-error {
  min-height: 1.4rem;
  margin: 0;
  color: #ff7b8f;
  text-align: center;
}

@media (max-width: 900px) {
  .auth-topbar {
    flex-direction: column;
