.chat-dock {
  position: fixed;
  right: 18px;
  left: auto;
  bottom: 18px;
  z-index: 120;
  display: grid;
  width: auto;
  max-width: calc(100vw - 20px);
  grid-template-columns: minmax(0, auto) auto;
  grid-template-rows: auto auto;
  grid-template-areas:
    "toast toast"
    "tabs launcher";
  align-items: end;
  justify-content: end;
  gap: 10px;
  pointer-events: none;
}

.chat-toast {
  grid-area: toast;
  justify-self: end;
  width: min(360px, calc(100vw - 40px));
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid rgba(148, 184, 255, 0.5);
  border-radius: 22px;
  background:
    radial-gradient(circle at top left, rgba(90, 169, 255, 0.26), transparent 42%),
    linear-gradient(135deg, rgba(15, 27, 54, 0.98), rgba(34, 91, 172, 0.95));
  color: #ffffff;
  box-shadow:
    0 26px 56px rgba(14, 31, 65, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.16);
  cursor: pointer;
  pointer-events: auto;
  transition:
    opacity 260ms ease,
    transform 260ms ease,
    filter 260ms ease;
  animation: chatToastEnter 360ms cubic-bezier(0.18, 0.9, 0.2, 1.15);
}

.chat-toast[hidden] {
  display: none;
}

.chat-toast.is-hiding {
  opacity: 0;
  transform: translateY(10px) scale(0.96);
  filter: saturate(0.86);
  pointer-events: none;
}

.chat-toast-avatar {
  width: 38px;
  height: 38px;
  border-radius: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  flex: 0 0 38px;
  background: rgba(255, 255, 255, 0.18);
  color: #ffffff;
  font-size: 0.78rem;
  font-weight: 800;
  position: relative;
}

.chat-toast-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.chat-toast-avatar::after {
  content: "";
  position: absolute;
  right: 3px;
  bottom: 3px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: 2px solid rgba(16, 30, 57, 0.96);
  background: #2fb36f;
}

.chat-toast-copy {
  min-width: 0;
  display: grid;
  gap: 3px;
  text-align: left;
}

.chat-toast-title-row {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.chat-toast-copy strong,
.chat-toast-copy span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chat-toast-copy strong {
  font-size: 0.86rem;
  letter-spacing: 0.01em;
}

.chat-toast-copy span {
  color: rgba(235, 244, 255, 0.82);
  font-size: 0.78rem;
}

.chat-toast-count {
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  background: rgba(255, 255, 255, 0.18);
  color: #ffffff;
  font-size: 0.68rem;
  font-weight: 800;
}

.chat-launcher {
  grid-area: launcher;
  align-self: end;
  pointer-events: auto;
  width: 50px;
  height: 50px;
  min-width: 50px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  padding: 0;
  border: 1px solid rgba(175, 198, 238, 0.88);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(236, 243, 255, 0.94));
  box-shadow:
    0 18px 34px rgba(38, 54, 90, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.94);
  color: #235dcf;
  cursor: pointer;
  position: relative;
  overflow: visible;
  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease,
    background 180ms ease;
}

.chat-launcher:hover {
  transform: translateY(-1px);
  border-color: rgba(91, 138, 223, 0.92);
  box-shadow:
    0 22px 40px rgba(44, 73, 132, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.96);
}

.chat-launcher-copy {
  display: none;
}

.chat-presence-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #98a4b7;
  box-shadow: 0 0 0 4px rgba(152, 164, 183, 0.12);
  flex: 0 0 10px;
}

.chat-presence-dot[data-presence="online"] {
  background: #2fb36f;
  box-shadow: 0 0 0 4px rgba(47, 179, 111, 0.14);
}

.chat-presence-dot[data-presence="away"] {
  background: #f1b44c;
  box-shadow: 0 0 0 4px rgba(241, 180, 76, 0.15);
}

.chat-presence-dot[data-presence="busy"] {
  background: #e06363;
  box-shadow: 0 0 0 4px rgba(224, 99, 99, 0.14);
}

.chat-presence-dot[data-presence="offline"] {
  background: #98a4b7;
}

.chat-launcher-presence {
  --chat-launcher-accent: rgba(76, 170, 242, 0.38);
  width: 100%;
  height: 100%;
  border-radius: inherit;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow:
    0 0 0 0 rgba(76, 170, 242, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.64);
  animation: chatLauncherPulse 2600ms ease-in-out infinite;
}

.chat-launcher-presence[data-presence="online"] {
  --chat-launcher-accent: rgba(47, 179, 111, 0.34);
}

.chat-launcher-presence[data-presence="away"] {
  --chat-launcher-accent: rgba(241, 180, 76, 0.34);
}

.chat-launcher-presence[data-presence="busy"] {
  --chat-launcher-accent: rgba(224, 99, 99, 0.34);
}

.chat-launcher-presence[data-presence="offline"] {
  --chat-launcher-accent: rgba(152, 164, 183, 0.28);
}

.chat-launcher-icon {
  width: 24px;
  height: 24px;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
  filter: drop-shadow(0 4px 10px rgba(61, 103, 198, 0.12));
}

.chat-launcher.has-unread {
  transform: translateY(-1px);
}

.chat-launcher.is-dock-collapsed:not(.has-unread) {
  box-shadow:
    0 20px 36px rgba(41, 74, 141, 0.18),
    0 0 0 5px rgba(63, 127, 234, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.94);
}

.chat-launcher.has-unread .chat-launcher-presence {
  animation: chatLauncherPulseStrong 1180ms ease-in-out infinite;
}

.chat-launcher-unread {
  position: absolute;
  top: -7px;
  right: -8px;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #d74388, #8d3bdf);
  color: #ffffff;
  font-size: 0.68rem;
  font-weight: 800;
  box-shadow: 0 10px 18px rgba(141, 59, 223, 0.28);
}

.chat-desktop-tabs {
  --chat-dock-visible-tabs: 3;
  --chat-dock-visible-gaps: 2;
  --chat-dock-tab-width: 206px;
  --chat-dock-tab-gap: 7px;
  grid-area: tabs;
  align-self: end;
  justify-self: end;
  width: auto;
  max-width: calc(100vw - 88px);
  min-width: 0;
  display: flex;
  align-items: stretch;
  gap: 8px;
  padding: 7px;
  border: 1px solid rgba(193, 207, 232, 0.82);
  border-radius: 24px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(236, 243, 255, 0.92));
  box-shadow:
    0 22px 44px rgba(42, 47, 74, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.96);
  pointer-events: auto;
}

.chat-desktop-tabs[hidden] {
  display: none;
}

.chat-desktop-tabs-scroller {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
}

.chat-desktop-tabs-actions {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
}

.chat-dock-nav,
.chat-dock-toggle {
  min-width: 36px;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 1px solid rgba(190, 204, 230, 0.94);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.92);
  color: #5f6f88;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    color 160ms ease;
}

.chat-dock-nav[hidden] {
  display: none;
}

.chat-dock-nav[disabled] {
  opacity: 0.42;
  cursor: default;
  box-shadow: none;
}

.chat-dock-nav:hover:not(:disabled),
.chat-dock-toggle:hover {
  transform: translateY(-1px);
  border-color: rgba(84, 128, 222, 0.42);
  color: #2e5fcb;
  box-shadow: 0 12px 22px rgba(47, 85, 158, 0.12);
}

.chat-dock-nav .icon-svg,
.chat-dock-toggle .icon-svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  stroke-width: 1.9;
  stroke-linecap: round;
  stroke-linejoin: round;
  fill: none;
}

.chat-conversation-menu {
