.vehicle-reservations-list {
  display: grid;
  gap: 10px;
}

.vehicle-reservation-item {
  border: 1px solid rgba(47, 104, 84, 0.12);
  border-radius: 18px;
  padding: 14px 16px;
  background: rgba(248, 250, 249, 0.96);
