  .offer-template-placeholder-list,
  .offers-form-grid,
  .offers-filters,
  .offer-item-main-grid,
  .offer-text-blocks,
  .offer-item-metrics {
    grid-template-columns: 1fr;
  }

  .offers-template-panel.is-modal-open,
  .offers-editor-panel.is-modal-open {
