.document-template-runtime-status-panel {
  order: 1;
  grid-column: 1;
  grid-row: 1;
  position: sticky;
  top: 82px;
  display: grid;
  gap: 12px;
  align-content: start;
  min-width: 0;
  max-width: 240px;
  padding: 14px 13px;
  border: 1px solid rgba(222, 226, 238, 0.96);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 18px 42px rgba(28, 38, 65, 0.08);
