.document-template-runtime-status-head strong {
  color: #111735;
  font-size: 0.94rem;
  line-height: 1.15;
}

.document-template-runtime-status-counter {
  display: inline-grid;
  place-items: center;
  min-width: 38px;
  height: 28px;
  padding: 0 9px;
  border-radius: 999px;
  background: rgba(124, 92, 255, 0.12);
  color: #4f2ed1;
  font-size: 0.76rem;
  font-weight: 900;
}

.document-template-runtime-status-progress {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: #edf0f7;
}

.document-template-runtime-status-progress > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #4f46e5, #7c3aed);
  box-shadow: 0 0 18px rgba(124, 58, 237, 0.3);
  transition: width 0.2s ease;
