  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  min-height: 58px;
  padding: 13px 14px 16px;
}

.ozo-worker-selected-strip span {
  background: #f8fafc;
  border: 1px solid #e5e7eb;
  border-radius: 999px;
  color: #0f172a;
  font-size: 12px;
  font-weight: 750;
  max-width: 100%;
  overflow: hidden;
  padding: 7px 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ozo-category-sidebar {
  align-self: start;
  display: grid;
  gap: 14px;
  padding: 14px;
}

.ozo-sidebar-head {
  align-items: center;
  background: #0f172a;
  border-radius: 8px;
  color: #ffffff;
  display: flex;
  justify-content: space-between;
  padding: 14px;
}

.ozo-sidebar-head strong {
  color: #facc15;
  font-size: 28px;
  line-height: 1;
}

.ozo-category-stack {
  display: grid;
  gap: 8px;
}

.ozo-category-metric {
  align-items: center;
  background: #f8fafc;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  display: flex;
  gap: 10px;
  justify-content: space-between;
  min-height: 42px;
  padding: 8px 10px;
}

.ozo-category-metric span {
  color: #334155;
  font-size: 12px;
  font-weight: 750;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ozo-category-metric strong {
  align-items: center;
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 999px;
  color: #0f172a;
  display: inline-flex;
  flex: 0 0 auto;
  font-size: 12px;
  height: 26px;
  justify-content: center;
  min-width: 34px;
  padding: 0 8px;
}

.ozo-selected-box {
  background: #fffbeb;
  border: 1px solid #fde68a;
  border-radius: 8px;
  display: grid;
  gap: 8px;
  padding: 14px;
}

.ozo-selected-box strong {
  color: #0f172a;
  font-size: 28px;
  line-height: 1;
}

.ozo-selected-box div {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.ozo-selected-box small {
  color: #334155;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.35;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ozo-sidebar-actions {
  display: grid;
  gap: 8px;
}

.ozo-sidebar-actions a,
.ozo-sidebar-actions button,
.ozo-new-actions button {
  align-items: center;
  border-radius: 8px;
  display: inline-flex;
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  justify-content: center;
  min-height: 42px;
  padding: 0 12px;
  text-decoration: none;
}

.ozo-sidebar-actions a {
  background: #ecfeff;
  border: 1px solid #bae6fd;
  color: #075985;
}

.ozo-sidebar-actions button,
.ozo-new-actions button {
  background: #0f172a;
  border: 1px solid #0f172a;
  color: #ffffff;
  cursor: pointer;
}

.ozo-equipment-panel {
  min-width: 0;
  padding: 14px;
}

.ozo-list-head {
  align-items: center;
  display: flex;
  gap: 12px;
  justify-content: space-between;
  margin-bottom: 12px;
}

.ozo-list-head > div {
  align-items: center;
  display: flex;
  gap: 8px;
}

.ozo-list-head span {
  color: #0f172a;
  font-size: 24px;
  font-weight: 850;
  line-height: 1;
}

.ozo-list-head strong {
  color: #0f172a;
  font-size: 14px;
  letter-spacing: 0;
}

.ozo-card-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(auto-fit, minmax(270px, 1fr));
  min-width: 0;
}

.ozo-equipment-card {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.06);
  cursor: pointer;
  display: grid;
  gap: 12px;
  min-width: 0;
  overflow: hidden;
  padding: 10px;
  position: relative;
  transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
}

.ozo-equipment-card:hover {
  border-color: rgba(250, 204, 21, 0.72);
  box-shadow: 0 18px 38px rgba(15, 23, 42, 0.12);
}

.ozo-equipment-card.is-selected {
  border-color: #facc15;
  box-shadow: 0 18px 42px rgba(250, 204, 21, 0.2);
}

.ozo-equipment-card input[type="checkbox"] {
  height: 1px;
  opacity: 0;
  pointer-events: none;
  position: absolute;
  width: 1px;
}

.ozo-card-media {
  aspect-ratio: 16 / 9;
  background: #f1f5f9;
  border-radius: 6px;
  display: block;
  overflow: hidden;
  position: relative;
}

.ozo-card-media > img {
  display: block;
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.ozo-card-icon {
  align-items: center;
  background: #0f172a;
  border: 3px solid #ffffff;
  border-radius: 999px;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.2);
  display: flex;
  height: 48px;
  justify-content: center;
  left: 10px;
  overflow: hidden;
  position: absolute;
  top: 10px;
  width: 48px;
}

.ozo-card-icon img {
  height: 34px;
  object-fit: contain;
  width: 34px;
}

.ozo-card-copy {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.ozo-card-kicker {
  color: #64748b;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.05em;
  overflow: hidden;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.ozo-card-copy strong {
  color: #0f172a;
  display: -webkit-box;
  font-size: 16px;
  font-weight: 850;
  line-height: 1.24;
  min-height: 40px;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.ozo-card-copy small {
  color: #0b58b4;
  display: block;
  font-size: 13px;
  font-weight: 800;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ozo-card-copy em {
  color: #475569;
  display: -webkit-box;
  font-size: 13px;
  font-style: normal;
  line-height: 1.4;
  min-height: 36px;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.ozo-card-footer {
  align-items: center;
  display: flex;
  gap: 8px;
  justify-content: space-between;
}

.ozo-status,
.ozo-select-pill {
  align-items: center;
  border-radius: 999px;
  display: inline-flex;
  font-size: 12px;
  font-weight: 850;
  min-height: 30px;
  padding: 0 10px;
}

.ozo-status.is-ready {
  background: #dcfce7;
  color: #15803d;
}

.ozo-select-pill {
  background: #f8fafc;
  border: 1px solid #e5e7eb;
  color: #0f172a;
}

.ozo-equipment-card.is-selected .ozo-select-pill {
  background: #facc15;
  border-color: #eab308;
}

.ozo-equipment-card.is-selected::after {
  align-items: center;
  background: #facc15;
  border: 2px solid #ffffff;
  border-radius: 999px;
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.18);
  color: #0f172a;
  content: "✓";
  display: flex;
  font-size: 14px;
  font-weight: 900;
  height: 28px;
  justify-content: center;
  position: absolute;
  right: 12px;
  top: 12px;
  width: 28px;
}

.ozo-new-form,
.ozo-selected-editor {
  display: grid;
  gap: 12px;
  margin-bottom: 18px;
  padding: 14px;
}

.ozo-new-form {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.ozo-new-form label,
.ozo-selected-row label {
  background: #f8fafc;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  display: grid;
  gap: 6px;
  min-width: 0;
  padding: 10px 12px;
}

.ozo-new-form label:focus-within,
.ozo-selected-row label:focus-within,
.ozo-search:focus-within {
  border-color: #facc15;
  box-shadow: 0 0 0 3px rgba(250, 204, 21, 0.18);
}

.ozo-new-form .is-wide {
  grid-column: span 2;
}

.ozo-new-actions {
  align-items: center;
  display: flex;
  gap: 12px;
  grid-column: span 3;
  justify-content: space-between;
}

.ozo-new-actions span {
  color: #64748b;
  font-size: 13px;
  line-height: 1.4;
}

.ozo-selected-editor {
  margin: 18px 0 0;
}

.ozo-selected-row {
  background: #ffffff;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  padding: 10px;
}

.ozo-selected-row .is-wide {
  grid-column: span 2;
}

.ozo-checkline {
  align-content: center;
  display: flex !important;
  flex-direction: row;
  gap: 8px !important;
}

.ozo-checkline input {
  accent-color: #facc15;
  height: 18px;
  width: 18px;
}

@media (max-width: 1360px) {
  .ozo-layout {
    grid-template-columns: minmax(360px, 1fr) minmax(360px, 1.2fr);
  }

  .ozo-category-sidebar {
    grid-column: 1 / -1;
    grid-template-columns: minmax(160px, 0.4fr) minmax(260px, 1fr) minmax(200px, 0.6fr) minmax(180px, 0.5fr);
  }

  .ozo-category-stack {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 980px) {
  .ozo-module {
    padding: 16px;
  }

  .ozo-module-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .ozo-filter-bar,
  .ozo-layout,
  .ozo-category-sidebar,
  .ozo-new-form,
  .ozo-selected-row {
    grid-template-columns: 1fr;
  }

  .ozo-category-stack {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ozo-new-form .is-wide,
  .ozo-new-actions,
  .ozo-selected-row .is-wide {
    grid-column: auto;
  }

  .ozo-new-actions {
    align-items: stretch;
    flex-direction: column;
  }
}

@media (max-width: 640px) {
  .ozo-module {
    padding: 12px;
  }

  .ozo-module-header h3 {
    font-size: 22px;
  }

  .ozo-filter-bar {
    max-width: 100%;
    min-width: 0;
    overflow: hidden;
    position: static;
  }

  .ozo-filter-chips {
    contain: paint;
    flex-wrap: wrap;
    margin: 0 -2px;
    max-width: 100%;
    overflow: hidden;
    padding: 2px;
    width: 100%;
  }

  .ozo-worker-hero {
    min-height: 220px;
  }

  .ozo-worker-summary,
  .ozo-category-stack,
  .ozo-card-grid {
    grid-template-columns: 1fr;
  }

  .ozo-attach-point small {
    display: none;
  }
}

/* Animated OZO worker preview */
.ozo-worker-hero {
  aspect-ratio: auto;
  background:
    radial-gradient(circle at 50% 86%, rgba(148, 163, 184, 0.22), transparent 34%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(241, 245, 249, 0.96)),
    repeating-linear-gradient(90deg, rgba(15, 23, 42, 0.035) 0 1px, transparent 1px 56px);
  min-height: 500px;
  padding: 18px;
}

.ozo-worker-hero > img,
.ozo-worker-gradient,
.ozo-gear,
.ozo-attach-point {
  display: none;
}

.ozo-worker-stage-copy {
  display: grid;
  gap: 4px;
  max-width: 62%;
  position: relative;
  z-index: 3;
}

.ozo-worker-stage-copy span {
  color: #64748b;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.ozo-worker-stage-copy strong {
  color: #0f172a;
  font-size: 18px;
  font-weight: 850;
  letter-spacing: 0;
  line-height: 1.18;
}

.ozo-stage-tags {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  justify-content: flex-end;
  left: 40%;
  position: absolute;
  right: 18px;
  top: 18px;
  z-index: 4;
}

.ozo-stage-tags span {
  background: rgba(255, 255, 255, 0.88);
  border: 1px solid rgba(226, 232, 240, 0.96);
  border-radius: 999px;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.08);
  color: #0f172a;
  font-size: 11px;
  font-weight: 850;
  line-height: 1;
  padding: 8px 10px;
  white-space: nowrap;
}

.ozo-animated-workers {
  align-items: end;
  bottom: 18px;
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  left: 18px;
  position: absolute;
  right: 18px;
  top: 82px;
  z-index: 2;
}

.ozo-worker-figure {
